-- Demo data for 01_schema.sql. Run as QLSV in FREEPDB1 (F5 / Run Script).
-- Repeatable: MERGE by CODE/USERNAME; existing rows are left unchanged.
-- DEMO ONLY: teacher/student accounts share password Demo@2026!; change before real use.
-- Admin account is created by Spring Boot AdminSeed using ADMIN_USERNAME/ADMIN_PASSWORD.
SET DEFINE OFF;

MERGE INTO COURSE_YEARS t USING (SELECT 'K24' AS CODE, 'Khóa 2024' AS NAME, 2024 AS START_YEAR FROM DUAL) s ON (t.CODE=s.CODE) WHEN NOT MATCHED THEN INSERT (CODE, NAME, START_YEAR) VALUES (s.CODE, s.NAME, s.START_YEAR);
MERGE INTO COURSE_YEARS t USING (SELECT 'K25' AS CODE, 'Khóa 2025' AS NAME, 2025 AS START_YEAR FROM DUAL) s ON (t.CODE=s.CODE) WHEN NOT MATCHED THEN INSERT (CODE, NAME, START_YEAR) VALUES (s.CODE, s.NAME, s.START_YEAR);
MERGE INTO COURSE_YEARS t USING (SELECT 'K26' AS CODE, 'Khóa 2026' AS NAME, 2026 AS START_YEAR FROM DUAL) s ON (t.CODE=s.CODE) WHEN NOT MATCHED THEN INSERT (CODE, NAME, START_YEAR) VALUES (s.CODE, s.NAME, s.START_YEAR);
MERGE INTO FACULTIES t USING (SELECT 'CNTT' AS CODE, 'Công nghệ thông tin' AS NAME, (SELECT ID FROM COURSE_YEARS WHERE CODE='K24') AS COURSE_YEAR_ID FROM DUAL) s ON (t.CODE=s.CODE) WHEN NOT MATCHED THEN INSERT (CODE, NAME, COURSE_YEAR_ID) VALUES (s.CODE, s.NAME, s.COURSE_YEAR_ID);
MERGE INTO FACULTIES t USING (SELECT 'QTKD' AS CODE, 'Quản trị kinh doanh' AS NAME, (SELECT ID FROM COURSE_YEARS WHERE CODE='K24') AS COURSE_YEAR_ID FROM DUAL) s ON (t.CODE=s.CODE) WHEN NOT MATCHED THEN INSERT (CODE, NAME, COURSE_YEAR_ID) VALUES (s.CODE, s.NAME, s.COURSE_YEAR_ID);
